y().astype(float)\ndf_h_all_scaled = pd.DataFrame(StandardScaler().fit_transform(df_h_all), columns=df_h_all.columns)\nagg1 = AgglomerativeClustering(n_clusters=2, linkage='ward')\nresults_h['agg_all'] = agg1.fit_predict(df_h_all_scaled)\n\n# Method 2: One-hot + Agglomerative\nnumerical_features = ['trestbps', 'chol', 'thalach', 'oldpeak']\ncategorical_features = ['sex', 'cp', 'fbs', 'restecg', 'exang', 'slope', 'ca', 'thal']\ndf_h_num = pd.DataFrame(StandardScaler().fit_transform(df_heart[numerical_features]), columns=numerical_features)\nencoder = OneHotEncoder(sparse_output=False, handle_unknown='ignore')\ndf_h_cat = pd.DataFrame(encoder.fit_transform(df_heart[categorical_features]),\n                        columns=encoder.get_feature_names_out(categorical_features))\ndf_h_onehot = pd.concat([df_h_num, df_h_cat], axis=1)\nagg2 = AgglomerativeClustering(n_clusters=2, linkage='ward')\nresults_h['agg_onehot'] = agg2.fit_predict(df_h_onehot)\n\n# Method 3: Key features weighted + KMeans\ndf_h3 = df_heart.copy().astype(float)\ndf_h3['cp'] = df_h3['cp'] * 2\ndf_h3['ca'] = df_h3['ca'] * 2\ndf_h3['thal'] = df_h3['thal'] * 2\ndf_h3['oldpeak'] = df_h3['oldpeak'] * 2\ndf_h3['exang'] = df_h3['exang'] * 2\ndf_h3['slope'] = df_h3['slope'] * 1.5\ndf_h3['thalach'] = df_h3['thalach'] * 1.5\ndf_h3_scaled = pd.DataFrame(StandardScaler().fit_transform(df_h3), columns=df_h3.columns)\nkm3 = KMeans(n_clusters=2, init='k-means++', n_init=100, random_state=42)\nresults_h['km_weighted'] = km3.fit_predict(df_h3_scaled)\n\n# Method 4: Key features only + Agglomerative\nkey_h = ['cp', 'thalach', 'oldpeak', 'ca', 'thal', 'exang', 'slope']\ndf_h4 = df_heart[key_h].copy().astype(float)\ndf_h4_scaled = pd.DataFrame(StandardScaler().fit_transform(df_h4), columns=key_h)\nagg4 = AgglomerativeClustering(n_clusters=2, linkage='ward')\nresults_h['agg_key'] = agg4.fit_predict(df_h4_scaled)\n\n# Method 5: Key features weighted + Agglomerative\ndf_h5 = df_heart[key_h].copy().astype(float)\ndf_h5['cp'] =