= {k: v for k, v in results_h.items() \n            if 400 <= sum(v==0) <= 625 and 400 <= sum(v==1) <= 625}\n\nprint(f\"\\nFiltered methods (balanced split): {list(filtered.keys())}\")\n\nif filtered:\n    best_avg = -1\n    best_k = None\n    for k1 in filtered:\n        total_ari = 0\n        count = 0\n        for k2 in filtered:\n            if k1 != k2:\n                ari = adjusted_rand_score(filtered[k1], filtered[k2])\n                total_ari += ari\n                count += 1\n        avg = total_ari / max(count, 1)\n        if avg > best_avg:\n            best_avg = avg\n            best_k = k1\n    best_heart = filtered[best_k]\n    print(f\"Selected: {best_k} (avg ARI among balanced = {best_avg:.4f})\")\nelse:\n    # fallback\n    best_heart = results_h['agg_all']\n    print(\"Fallback: agg_all\")\n\nprint(f\"Final heart: {sum(best_heart==0)}/{sum(best_heart==1)}\")\n\n# ===================== SAVE =====================\nout_diabetes = pd.DataFrame({'pseudo_label': best_diabetes})\nout_diabetes.to_csv('/app/output_diabetes_data.csv', index=False)\nprint(f\"\\nSaved diabetes: {out_diabetes['pseudo_label'].value_counts().to_dict()}\")\n\nout_heart = pd.DataFrame({'pseudo_label': best_heart})\nout_heart.to_csv('/app/output_heart.csv', index=False)\nprint(f\"Saved heart: {out_heart['pseudo_label'].value_counts().to_dict()}\")\nprint(\"Done!\")\nEOF\n",
